      "content": "using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using FunnySharp;

public static class FeedCleaner
{
    public static CleanOutcome Clean(
        IReadOnlyList<RawRow> rows,
        IReadOnlyList<string> categories,
        SkuCatalog catalog)
    {
        ArgumentNullException.ThrowIfNull(rows);
        ArgumentNullException.ThrowIfNull(categories);

        // Reject malformed feeds before enumerating or checking any row.
        if (rows.Count != categories.Count)
        {
            return LengthMismatch();
        }

        ArgumentNullException.ThrowIfNull(catalog);

        // Exact pairing never silently truncates either input.
        if (!rows.ZipExactOrNone(categories).TryGetValue(out var pairs))
        {
            return LengthMismatch();
        }

        var importedSkus = new HashSet<string>(StringComparer.Ordinal);

        // Partition consumes the checks once, in source order, preserving order
        // within both the imported and dropped sides.
        var partition = pairs!
            .Select((pair, index) => CleanRow(
                pair.First,
                pair.Second,
                index + 1,
                catalog,
                importedSkus))
            .Partition();

        decimal? averagePrice = partition.Passed
            .Select(product => product.Price)
            .ToNonEmptyOrNone()
            .Match<decimal?>(
                prices => Math.Round(
                    prices.Aggregate(static (sum, price) => sum + price) / prices.Count,
                    2,
                    MidpointRounding.AwayFromZero),
                () => null);

        return new CleanOutcome(
            partition.Passed,
            partition.Failed,
            Array.Empty<string>(),
            averagePrice);
    }

    private static Result<Product, DroppedRow> CleanRow(
        RawRow row,
        string category,
        int line,
        SkuCatalog catalog,
        HashSet<string> importedSkus)
    {
        var sku = row.Sku;
        if (string.IsNullOrWhiteSpace(sku))
        {
            return Drop(line, "blank-sku");
        }

        var name = row.Name;
        if (string.IsNullOrWhiteSpace(name))
        {
            return Drop(line, "blank-name");
        }

        var normalizedSku = sku.Trim().ToUpperInvariant();
        if (!catalog.IsKnown(normalizedSku))
        {
            return Drop(line, "unknown-sku");
        }

        if (!decimal.TryParse(
            row.PriceText?.Trim(),
            NumberStyles.Number,
            CultureInfo.InvariantCulture,
            out var price))
        {
            return Drop(line, "invalid-price");
        }

        // Only a row that passes all preceding checks may reserve its sku.
        if (!importedSkus.Add(normalizedSku))
        {
            return Drop(line, "duplicate-sku");
        }

        return Result<Product, DroppedRow>.Success(
            new Product(normalizedSku, name.Trim(), price, category));
    }

    private static Result<Product, DroppedRow> Drop(int line, string reason) =>
        Result<Product, DroppedRow>.Failure(new DroppedRow(line, reason));

    private static CleanOutcome LengthMismatch() =>
        new CleanOutcome(
            Array.Empty<Product>(),
            Array.Empty<DroppedRow>(),
            new[] { "length-mismatch" },
            null);
}
"
    }
  ]
}

